  const billed = monthlyInvoices.get(monthKey) ?? 0, totalBilled = [...annualInvoices.values()].reduce((sum, value) => sum + value, 0), averageInvoice = invoices.length ? totalBilled / invoices.length : 0, annualInvoiceSeries = [...annualInvoices.entries()].sort(([a], [b]) => a.localeCompare(b)), latestAnnual = annualInvoiceSeries.at(-1), previousAnnual = annualInvoiceSeries.at(-2), latestGrowth = latestAnnual && previousAnnual && previousAnnual[1] ? (latestAnnual[1] / previousAnnual[1] - 1) * 100 : null, recurringClients = [...invoiceClients.values()].filter((item) => item.count > 1).length, recurringRate = invoiceClients.size ? recurringClients / invoiceClients.size * 100 : 0;
