  const categories = new Map<string, number>(), merchants = new Map<string, number>(), months = new Map<string, number>();
  filtered.forEach((record) => { const value = Math.abs(numberValue(record.values[valueIndex])), category = fixEncoding(record.values[categoryIndex] || "Sem categoria"), merchant = fixEncoding(record.values[merchantIndex] || "Não identificado"), month = isoDate(record.values[dateIndex] ?? "").slice(0, 7); categories.set(category, (categories.get(category) ?? 0) + value); merchants.set(merchant, (merchants.get(merchant) ?? 0) + value); if (month) months.set(month, (months.get(month) ?? 0) + value); });
  const categoryRanking = [...categories.entries()].sort((a, b) => b[1] - a[1]).slice(0, 8), merchantRanking = [...merchants.entries()].sort((a, b) => b[1] - a[1]).slice(0, 8), maxCategory = Math.max(1, ...categoryRanking.map(([, value]) => value)), maxMerchant = Math.max(1, ...merchantRanking.map(([, value]) => value)), latestMonth = [...months.entries()].sort(([a], [b]) => a.localeCompare(b)).at(-1);
